import org.bukkit.entity.Player;
import org.bukkit.event.inventory.InventoryClickEvent;

public class ConfirmGui {

    public static void open(Player player, BountyPlugin plugin, OfflinePlayer target, long amount) {
        Gui gui = Gui.gui()
                .title(ChatUtils.format(plugin.getConfig().getString("confirm-gui.title")))
                .rows(plugin.getConfig().getInt("confirm-gui.rows"))
                .disableAllInteractions().create();

        setItem(plugin, "confirm-gui.items.info", gui, target.getName(), amount, event -> {
        });
        setItem(plugin, "confirm-gui.items.cancel", gui, target.getName(), amount, event -> gui.close(player));
        setItem(plugin, "confirm-gui.items.confirm", gui, target.getName(), amount, event -> {
            gui.close(player);

            BountyResult result = plugin.getBountyManager().addBounty(player, target.getUniqueId(), amount);
            switch (result) {
                case SUCCESS -> {
                    if (target.isConnected()) {
                        ChatUtils.sendMessage(target.getPlayer(), ChatUtils.format(
                                plugin.getConfig().getString("messages.bounty-added-to-you"),
                                Placeholder.unparsed("amount", ChatUtils.FORMATTER.format(amount)),
                                Placeholder.unparsed("player", player.getName())
                        ));
                    }

                    ChatUtils.sendMessage(player, ChatUtils.format(
                            plugin.getConfig().getString("messages.bounty-added"),
                            Placeholder.unparsed("amount", ChatUtils.FORMATTER.format(amount)),
                            Placeholder.unparsed("player", target.getName() == null ? "---" : target.getName())
                    ));
                    plugin.getScheduler().runAtEntity(player, _task -> player.playSound(Sound.sound(Key.key(plugin.getConfig().getString("settings.sounds.success")), Sound.Source.MASTER, 1.0f, 1.0f)));
                }
                case MAXIMUM_EXCEEDED -> {
                    plugin.getScheduler().runAtEntity(player, _task -> player.playSound(Sound.sound(Key.key(plugin.getConfig().getString("settings.sounds.fail")), Sound.Source.MASTER, 1.0f, 1.0f)));
                    ChatUtils.sendMessage(player, ChatUtils.format(plugin.getConfig().getString("messages.maximum-bounty")));
                }
                case INVALID_AMOUNT -> {
                    plugin.getScheduler().runAtEntity(player, _task -> player.playSound(Sound.sound(Key.key(plugin.getConfig().getString("settings.sounds.fail")), Sound.Source.MASTER, 1.0f, 1.0f)));
                    ChatUtils.sendMessage(player, ChatUtils.format(plugin.getConfig().getString("messages.minimum-bounty")));
                }
                case NOT_ENOUGH_MONEY -> {
                    plugin.getScheduler().runAtEntity(player, _task -> player.playSound(Sound.sound(Key.key(plugin.getConfig().getString("settings.sounds.fail")), Sound.Source.MASTER, 1.0f, 1.0f)));
                    ChatUtils.sendMessage(player, ChatUtils.format(plugin.getConfig().getString("messages.not-enough-money")));
                }
                case BAD_STATS_KD -> {
                    plugin.getScheduler().runAtEntity(player, _task -> player.playSound(Sound.sound(Key.key(plugin.getConfig().getString("settings.sounds.fail")), Sound.Source.MASTER, 1.0f, 1.0f)));
                    double kd = plugin.getBountyManager().getPlayerKD(target.getUniqueId());
                    ChatUtils.sendMessage(player, ChatUtils.format(
                            plugin.getConfig().getString("messages.bad-stats-kd"),
                            Placeholder.unparsed("kd", String.format("%.2f", kd)),
                            Placeholder.unparsed("min_kd", String.format("%.2f", plugin.getBountyManager().getMinimumKd()))
                    ));
                }
                case BAD_STATS_DEATHS -> {
                    plugin.getScheduler().runAtEntity(player, _task -> player.playSound(Sound.sound(Key.key(plugin.getConfig().getString("settings.sounds.fail")), Sound.Source.MASTER, 1.0f, 1.0f)));
                    int deaths = plugin.getBountyManager().getPlayerDeaths(target.getUniqueId());
                    ChatUtils.sendMessage(player, ChatUtils.format(
                            plugin.getConfig().getString("messages.bad-stats-deaths"),
                            Placeholder.unparsed("deaths", String.valueOf(deaths)),
                            Placeholder.unparsed("max_deaths", String.valueOf(plugin.getBountyManager().getMaximumDeaths()))
                    ));
                }
            }
        });

        gui.setCloseGuiAction(event -> {
            plugin.getScheduler().runAtEntity(player, _task -> player.playSound(Sound.sound(Key.key(plugin.getConfig().getString("settings.sounds.cancel")), Sound.Source.MASTER, 1.0f, 1.0f)));
        });

        gui.open(player);
    }

    private static void setItem(BountyPlugin plugin, String path, Gui gui, String playerName, long amount, GuiAction<InventoryClickEvent> action) {
        gui.setItem(plugin.getConfig().getInt(path + ".slot"),
                PaperItemBuilder.from(Material.valueOf(plugin.getConfig().getString(path + ".material")))
                        .name(ChatUtils.format(plugin.getConfig().getString(path + ".name"),
                                Placeholder.unparsed("player", playerName),
                                Placeholder.unparsed("bounty", ChatUtils.FORMATTER.format(amount))
                        ))
                        .lore(ChatUtils.format(plugin.getConfig().getStringList(path + ".lore"),
                                Placeholder.unparsed("player", playerName),
                                Placeholder.unparsed("bounty", ChatUtils.FORMATTER.format(amount))
                        )).asGuiItem(action));
    }

}

package dev.vireon.bounty.util;

import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.TextDecoration;
import net.kyori.adventure.text.minimessage.MiniMessage;
import net.kyori.adventure.text.minimessage.tag.resolver.TagResolver;
import net.kyori.adventure.text.serializer.legacy.LegacyComponentSerializer;
import org.bukkit.command.CommandSender;

import java.text.NumberFormat;
import java.text.SimpleDateFormat;
import java.util.List;
import java.util.stream.Collectors;

public class ChatUtils {

    public static final NumberFormat FORMATTER = NumberFormat.getCompactNumberInstance();
    public static final LegacyComponentSerializer LEGACY = LegacyComponentSerializer.builder().character('&').hexColors().build();
    public static final LegacyComponentSerializer LEGACY_AMPERSAND = LegacyComponentSerializer.builder().hexColors().build();
    public static final SimpleDateFormat DATE_FORMAT = new SimpleDateFormat("dd/MM/yyyy HH:mm:ss");
    private final static MiniMessage MINI_MESSAGE = MiniMessage.builder()
            .tags(TagResolver.standard())
            .postProcessor(component -> component.decoration(TextDecoration.ITALIC, false))
            .build();

    static {
        FORMATTER.setMinimumIntegerDigits(1);
        FORMATTER.setMaximumIntegerDigits(20);
        FORMATTER.setMaximumFractionDigits(2);
    }

    public static String fromLegacy(Component component) {
        return LEGACY_AMPERSAND.serialize(component);
    }

    public static Component colorLegacyString(String string) {
        return LEGACY.deserialize(string);
    }

    public static String toLegacy(String string, TagResolver... placeholders) {
        Component component = ChatUtils.format(string, placeholders);
        return LEGACY.serialize(component);
    }

    public static List<String> toLegacy(List<String> list, TagResolver... placeholders) {
        return list.stream().map(s -> toLegacy(s, placeholders)).collect(Collectors.toList());
    }

    public static Component format(String string, TagResolver... placeholders) {
        return MINI_MESSAGE.deserialize(string, placeholders);
    }

    public static List<Component> format(List<String> list, TagResolver... placeholders) {
        return list.stream().map(s -> MINI_MESSAGE.deserialize(s, placeholders)).collect(Collectors.toList());
    }

    public static void sendMessage(CommandSender player, Component component) {
        player.sendMessage(component);
    }

    public static void sendMessage(CommandSender player, List<Component> components) {
        components.forEach(s -> ChatUtils.sendMessage(player, s));
    }

}

