import de.rapha149.signgui.exception.SignGUIVersionException;
import dev.triumphteam.gui.builder.item.PaperItemBuilder;
import dev.triumphteam.gui.builder.item.SkullBuilder;
import dev.triumphteam.gui.components.GuiAction;
import dev.triumphteam.gui.guis.Gui;
import dev.triumphteam.gui.guis.PaginatedGui;
import dev.vireon.bounty.BountyPlugin;
import dev.vireon.bounty.bounty.Bounty;
import dev.vireon.bounty.bounty.BountyIndex;
import dev.vireon.bounty.util.ChatUtils;
import net.kyori.adventure.key.Key;
import net.kyori.adventure.sound.Sound;
import net.kyori.adventure.text.minimessage.tag.resolver.Placeholder;
import org.bukkit.DyeColor;
import org.bukkit.Material;
import org.bukkit.entity.Player;
import org.bukkit.event.inventory.InventoryClickEvent;

import javax.annotation.Nullable;
import java.util.Collection;
import java.util.List;
import java.util.UUID;
import java.util.concurrent.TimeUnit;

public class MainGui {

    private static final Cache<UUID, Byte> CLICK_CACHE = CacheBuilder.newBuilder().expireAfterWrite(1, TimeUnit.SECONDS).build();

    public static void open(Player player, BountyIndex.SortField sort, @Nullable String filter, BountyPlugin plugin) {
        PaginatedGui gui = Gui.paginated()
                .title(ChatUtils.format(plugin.getConfig().getString("gui.title")))
                .rows(plugin.getConfig().getInt("gui.rows"))
                .pageSize(plugin.getConfig().getInt("gui.page-size"))
                .disableAllInteractions().create();

        Collection<Bounty> bounties = switch (sort) {
            case AMOUNT -> plugin.getBountyManager().getBountyMap().listAllByAmount();
            case NAME -> plugin.getBountyManager().getBountyMap().listByName();
            case LAST_UPDATED -> plugin.getBountyManager().getBountyMap().listAllByLastUpdated();
        };

        if (filter != null && !filter.isEmpty()) {
            bounties.removeIf(bounty -> !bounty.getPlayerName().toLowerCase().contains(filter.toLowerCase()));
        }

        for (Bounty bounty : bounties) {
            SkullBuilder builder;
            if (bounty.getSkinTexture() != null) builder = PaperItemBuilder.skull().texture(bounty.getSkinTexture());
            else builder = PaperItemBuilder.skull();

            gui.addItem(builder
                    .name(ChatUtils.format(plugin.getConfig().getString("gui.items.bounty.name"),
                            Placeholder.unparsed("player", bounty.getPlayerName())))
                    .lore(ChatUtils.format(plugin.getConfig().getStringList("gui.items.bounty.lore"),
                            Placeholder.unparsed("bounty", ChatUtils.FORMATTER.format(bounty.getAmount()))))
                    .asGuiItem());
        }

        setItem(plugin, "gui.items.info", sort, gui, event -> {
            if (CLICK_CACHE.getIfPresent(player.getUniqueId()) != null) {
                plugin.getScheduler().runAtEntity(player, task -> player.playSound(Sound.sound(Key.key(plugin.getConfig().getString("settings.sounds.fail")), Sound.Source.MASTER, 1.0f, 1.0f)));
                ChatUtils.sendMessage(player, ChatUtils.format(plugin.getConfig().getString("messages.click-cooldown")));
                return;
            }

            CLICK_CACHE.put(player.getUniqueId(), (byte) 0);

            plugin.getScheduler().runAtEntity(player, task -> player.playSound(Sound.sound(Key.key(plugin.getConfig().getString("settings.sounds.success")), Sound.Source.MASTER, 1.0f, 1.0f)));
            open(player, sort, filter, plugin);
        });
        setItem(plugin, "gui.items.previous-page", sort, gui, event -> gui.previous());
        setItem(plugin, "gui.items.next-page", sort, gui, event -> gui.next());
        setItem(plugin, "gui.items.sort", sort, gui, event -> {
            if (CLICK_CACHE.getIfPresent(player.getUniqueId()) != null) {
                plugin.getScheduler().runAtEntity(player, task -> player.playSound(Sound.sound(Key.key(plugin.getConfig().getString("settings.sounds.fail")), Sound.Source.MASTER, 1.0f, 1.0f)));
                ChatUtils.sendMessage(player, ChatUtils.format(plugin.getConfig().getString("messages.click-cooldown")));
                return;
            }

            CLICK_CACHE.put(player.getUniqueId(), (byte) 0);

            plugin.getScheduler().runAtEntity(player, task -> player.playSound(Sound.sound(Key.key(plugin.getConfig().getString("settings.sounds.success")), Sound.Source.MASTER, 1.0f, 1.0f)));
            open(player, sort.next(), filter, plugin);
        });
        setItem(plugin, "gui.items.search", sort, gui, event -> {
            if (plugin.getFoliaLib().isFolia()) {
                plugin.getScheduler().runAtEntity(player, _task -> player.playSound(Sound.sound(Key.key(plugin.getConfig().getString("settings.sounds.fail")), Sound.Source.MASTER, 1.0f, 1.0f)));
                return;
            }

            try {
                SignGUI signGUI = SignGUI.builder()
                        .setAdventureLines(ChatUtils.format(plugin.getConfig().getStringList("messages.sign.lines")).toArray())
                        .setType(Material.valueOf(plugin.getConfig().getString("messages.sign.material", "OAK_SIGN").toUpperCase()))
                        .setColor(DyeColor.valueOf(plugin.getConfig().getString("messages.sign.color", "WHITE").toUpperCase()))
                        .setGlow(plugin.getConfig().getBoolean("messages.sign.glow"))
                        .setHandler((p, result) -> {
                            String input = result.getLine(0);
                            if (input == null || input.isEmpty()) {
                                return List.of(
                                        SignGUIAction.run(() -> plugin.getScheduler().runAtEntity(player, task -> open(player, sort, null, plugin))),
                                        SignGUIAction.run(() -> plugin.getScheduler().runAtEntity(player, task -> player.playSound(Sound.sound(Key.key(plugin.getConfig().getString("settings.sounds.fail")), Sound.Source.MASTER, 1.0f, 1.0f))))
                                );
                            }

                            return List.of(
                                    SignGUIAction.run(() -> plugin.getScheduler().runAtEntity(player, task -> open(player, sort, input, plugin))),
                                    SignGUIAction.run(() -> plugin.getScheduler().runAtEntity(player, task -> player.playSound(Sound.sound(Key.key(plugin.getConfig().getString("settings.sounds.success")), Sound.Source.MASTER, 1.0f, 1.0f))))
                            );
                        })
                        .build();

                signGUI.open(player);
            } catch (SignGUIVersionException e) {
                throw new RuntimeException(e);
            }
        });

        gui.open(player);
    }

    private static void setItem(BountyPlugin plugin, String path, BountyIndex.SortField sort, PaginatedGui gui, GuiAction<InventoryClickEvent> action) {
        if (plugin.getConfig().getInt(path + ".slot") < 0) return;

        gui.setItem(plugin.getConfig().getInt(path + ".slot"),
                PaperItemBuilder.from(Material.valueOf(plugin.getConfig().getString(path + ".material")))
                        .name(ChatUtils.format(plugin.getConfig().getString(path + ".name")))
                        .lore(ChatUtils.format(plugin.getConfig().getStringList(path + ".lore"),
                                Placeholder.parsed("sort", plugin.getConfig().getString("messages.sort-types." + sort.name(), sort.name()))))
                        .asGuiItem(action));
    }

}

package dev.vireon.bounty.bounty;

import dev.vireon.bounty.BountyPlugin;
import dev.vireon.bounty.util.SkinUtils;
import lombok.Getter;
import lombok.RequiredArgsConstructor;
import org.bukkit.Bukkit;
import org.bukkit.OfflinePlayer;
import org.bukkit.Statistic;
import org.bukkit.entity.Player;

import java.util.Collection;
import java.util.UUID;

@RequiredArgsConstructor
public class BountyManager {

    private final BountyPlugin plugin;

    // Map to store bounties by player UUID
    @Getter
    private final BountyIndex bountyMap = new BountyIndex();

    @Getter
    private long max = -1;
    @Getter
    private long min = 1;

    // Tax configuration
    @Getter
    private double tax = -1;

    // Stat blocking configuration
    @Getter
    private boolean statBlockingEnabled = false;
    @Getter
    private String statBlockingMode = "kd";
    @Getter
    private double minimumKd = 0.5;
    @Getter
    private int maximumDeaths = 100;

    public void init() {
        max = plugin.getConfig().getLong("settings.maximum-bounty", 100_000_000);
        min = plugin.getConfig().getLong("settings.minimum-bounty", 1L);

        // Load tax configuration
        tax = plugin.getConfig().getDouble("settings.tax", -1);

        // Load stat blocking configuration
        statBlockingEnabled = plugin.getConfig().getBoolean("settings.stat-blocking.enabled", false);
        statBlockingMode = plugin.getConfig().getString("settings.stat-blocking.mode", "kd");
        minimumKd = plugin.getConfig().getDouble("settings.stat-blocking.minimum-kd", 0.5);
        maximumDeaths = plugin.getConfig().getInt("settings.stat-blocking.maximum-deaths", 100);
    }

    public BountyResult addBounty(Player player, UUID playerId, long amount) {
        Bounty currentBounty = bountyMap.get(playerId).orElse(null);
        if (max != -1 && amount > max) return BountyResult.MAXIMUM_EXCEEDED;
        if (amount < min) return BountyResult.INVALID_AMOUNT;
        if (!plugin.getEconomyManager().has(player, amount)) return BountyResult.NOT_ENOUGH_MONEY;

        // Check player stats if stat blocking is enabled
        if (statBlockingEnabled) {
            BountyResult statResult = checkPlayerStats(playerId);
            if (statResult != BountyResult.SUCCESS) {
                return statResult;
            }
        }

        if (currentBounty == null) {
            OfflinePlayer offlinePlayer = Bukkit.getOfflinePlayer(playerId);
            Bounty bounty = new Bounty(playerId, offlinePlayer.getName(), SkinUtils.getSkin(offlinePlayer), amount, System.currentTimeMillis());
            bountyMap.put(bounty);
        } else {
            bountyMap.addAmount(playerId, amount);
            bountyMap.touchLastUpdated(playerId, System.currentTimeMillis());
        }

        plugin.getEconomyManager().remove(player, amount);

        return BountyResult.SUCCESS;
    }

    public Bounty getBounty(UUID playerId) {
        return bountyMap.get(playerId).orElse(null);
    }

    public Collection<Bounty> getAllBounties(BountyIndex.SortField sortField) {
        return bountyMap.listAll(sortField);
    }

    public void removeBounty(UUID playerId) {
        bountyMap.remove(playerId);
        plugin.getDatabase().removeBounty(playerId);
    }

    /**
     * Check if a player meets the stat requirements for having a bounty placed on them
     * @param playerId The UUID of the player to check
     * @return BountyResult.SUCCESS if stats are acceptable, or a specific error result
     */
    private BountyResult checkPlayerStats(UUID playerId) {
        OfflinePlayer offlinePlayer = Bukkit.getOfflinePlayer(playerId);

        // If player has never played, they have no stats, so block the bounty
        if (!offlinePlayer.hasPlayedBefore()) {
            // Treat new players as having bad stats
            return "kd".equals(statBlockingMode) ? BountyResult.BAD_STATS_KD : BountyResult.BAD_STATS_DEATHS;
        }

        // Now we can check stats for both online and offline players using OfflinePlayer.getStatistic()
        // Paper API 1.19+ supports statistics for offline players
        if ("kd".equals(statBlockingMode)) {
            // Check K/D ratio using helper method
            double kd = getPlayerKD(playerId);
            return kd >= minimumKd ? BountyResult.SUCCESS : BountyResult.BAD_STATS_KD;
        } else {
            // Check maximum deaths using helper method
            int deaths = getPlayerDeaths(playerId);
            return deaths <= maximumDeaths ? BountyResult.SUCCESS : BountyResult.BAD_STATS_DEATHS;
        }
    }

    /**
     * Get the K/D ratio for a player (for error messages)
     * @param playerId The UUID of the player
     * @return The K/D ratio, or 0.0 if unable to calculate
     */
    public double getPlayerKD(UUID playerId) {
        OfflinePlayer offlinePlayer = Bukkit.getOfflinePlayer(playerId);

        // Use OfflinePlayer.getStatistic() which works for both online and offline players
        // Paper API 1.19+ supports statistics for offline players
        if (!offlinePlayer.hasPlayedBefore()) return 0.0;

        int kills = offlinePlayer.getStatistic(Statistic.PLAYER_KILLS);
        int deaths = offlinePlayer.getStatistic(Statistic.DEATHS);

        return deaths == 0 ? kills : (double) kills / deaths;
    }

    /**
     * Get the death count for a player (for error messages)
     * @param playerId The UUID of the player
     * @return The death count, or 0 if unable to get
     */
    public int getPlayerDeaths(UUID playerId) {
        OfflinePlayer offlinePlayer = Bukkit.getOfflinePlayer(playerId);

        // Use OfflinePlayer.getStatistic() which works for both online and offline players
        // Paper API 1.19+ supports statistics for offline players
        if (!offlinePlayer.hasPlayedBefore()) return 0;

        return offlinePlayer.getStatistic(Statistic.DEATHS);
    }

    /**
     * Calculate the after-tax amount for a bounty claim
     * @param originalAmount The original bounty amount
     * @return The amount after tax deduction, or original amount if tax is disabled
     */
    public long calculateAfterTaxAmount(long originalAmount) {
        // Tax disabled if negative value
        if (tax < 0) {
            return originalAmount;
        }

        // Calculate tax amount and subtract from original
        double taxAmount = originalAmount * (tax / 100.0);
        return Math.max(0, originalAmount - (long) taxAmount);
    }

}

package dev.vireon.bounty.economy.impl;

import dev.vireon.bounty.economy.EconomyManager;
import net.milkbowl.vault.economy.Economy;
import org.bukkit.Bukkit;
import org.bukkit.OfflinePlayer;
import org.bukkit.plugin.RegisteredServiceProvider;

public class VaultEconomyManager implements EconomyManager {

    private Economy economy = null;

    public void init() {
        RegisteredServiceProvider<Economy> rsp = Bukkit.getServer().getServicesManager().getRegistration(Economy.class);
        if (rsp == null) return;

        economy = rsp.getProvider();
    }

    public void remove(OfflinePlayer player, double amount) {
        economy.withdrawPlayer(player, amount);
    }

    public void add(OfflinePlayer player, double amount) {
        economy.depositPlayer(player, amount);
    }

    public double getMoney(OfflinePlayer player) {
        return economy.getBalance(player);
    }

    public void setMoney(OfflinePlayer player, double amount) {
        this.remove(player, this.getMoney(player));
        this.add(player, amount);
    }

}
